window.EXAUD={"Please adjust the volume of the TV.": "../communication/audio/cau/a86602221c5c9e92.mp3", "It takes time to adjust to a new school.": "../communication/audio/cau/61f3abc92e9c4acc.mp3", "The air in the countryside is fresh.": "../a-closer-look-1/audio/cau/c976ff78f2c2738c.mp3", "Open the window to let some fresh air in.": "../a-closer-look-1/audio/cau/d1639d8ab7bbcd46.mp3", "Are you alright?": "../communication/audio/cau/95fa4f06b887983c.mp3", "Alright, let's start the game.": "../communication/audio/cau/bd559e3cc83839db.mp3", "Lan likes music. She also likes drawing.": "../a-closer-look-2/audio/cau/a42927a6760bdc56.mp3", "Nam speaks English and also learns Japanese.": "../a-closer-look-2/audio/cau/d657bddc45a35d0d.mp3", "Tom is American.": "../a-closer-look-2/audio/cau/ae2f18c3e637b195.mp3", "I like American films.": "../a-closer-look-2/audio/cau/87660b26ab942170.mp3", "What animal room would you like to create?": "../a-closer-look-1/audio/cau/5e05fc71d8b0c067.mp3", "A tiger is a big animal.": "../a-closer-look-1/audio/cau/d1413c566bc88fdb.mp3", "My brother loves drawing animals.": "../a-closer-look-1/audio/cau/05c49969296ecc10.mp3", "A cat is a small animal, but an elephant is big.": "../a-closer-look-1/audio/cau/6225cb8856b5304b.mp3", "Please answer the teacher's question.": "../a-closer-look-1/audio/cau/f790ccdd60f40ece.mp3", "Nam asks and Hoa answers.": "../a-closer-look-1/audio/cau/128cffcafde831b9.mp3", "Mai answered all the questions in the quiz.": "audio/cau/c93d065e33503510.mp3", "Khoa answered \"Yes\" to question 3.": "audio/cau/0f875ac2987d5d20.mp3", "I appreciate your help.": "../skills-1/audio/cau/48593d0b17d14cdf.mp3", "We should appreciate our parents.": "../skills-1/audio/cau/a7311bb07b419f89.mp3", "Mi and Nam are in Class 6A.": "../a-closer-look-1/audio/cau/b0d165e52ca7dc85.mp3", "We are happy today, and Lan is happy too.": "../a-closer-look-1/audio/cau/9718e7702bade08e.mp3", "Some areas of the city are very crowded.": "../a-closer-look-1/audio/cau/4154bcc5089d94ca.mp3", "This area is quiet, but other areas are noisy.": "../a-closer-look-1/audio/cau/69ea3ec6b58e98ab.mp3", "Pham Tuan was the first Vietnamese astronaut.": "../a-closer-look-2/audio/cau/e71cf0d258d6fe24.mp3", "I want to be an astronaut.": "../a-closer-look-2/audio/cau/d228facaad917608.mp3", "The average age of the class is 12.": "../a-closer-look-1/audio/cau/88cc3876de3fb381.mp3", "On average, I sleep eight hours a day.": "../a-closer-look-1/audio/cau/f790bf42c68fcb51.mp3", "We want to raise awareness about pollution.": "../skills-1/audio/cau/7a4e8fdce1cc80a5.mp3", "Public awareness of health is growing.": "../skills-1/audio/cau/d2bcf95bdad75fd3.mp3", "Look at picture b and answer.": "../a-closer-look-1/audio/cau/b2672a8a1898ddda.mp3", "Write the letter b next to the right answer.": "../a-closer-look-1/audio/cau/9ec7b58bf879e0bc.mp3", "He came back to his village after the war.": "audio/cau/97697c4a9d748fa3.mp3", "Nam went to Hue and came back on Sunday.": "audio/cau/1bf8eb10f268125e.mp3", "Try to keep a balance between study and play.": "../a-closer-look-1/audio/cau/44d0699cbae934ba.mp3", "A balanced diet helps you keep a good balance in life.": "../a-closer-look-1/audio/cau/20a258cd4a2dfe22.mp3", "My grandfather makes baskets from bamboo.": "../a-closer-look-1/audio/cau/570bf04fb5e0d256.mp3", "Bamboo grows fast, and artisans use it to make many things.": "../a-closer-look-1/audio/cau/ffc642fbc938aee9.mp3", "Ha Long Bay is a World Heritage Site.": "../a-closer-look-2/audio/cau/5a085a89254963b8.mp3", "There are thousands of islands in the bay.": "../a-closer-look-2/audio/cau/4cf873f6cc8fd985.mp3", "Please be quiet in the library.": "../a-closer-look-1/audio/cau/d6fab02a2655be4e.mp3", "I want to be a doctor. My sister is a nurse.": "../a-closer-look-1/audio/cau/e31166f3ca032296.mp3", "My sister has a big teddy bear.": "../a-closer-look-2/audio/cau/308925e32424fd06.mp3", "A bear is a big animal with thick fur.": "../a-closer-look-2/audio/cau/d04318a110c4d5fd.mp3", "Hoi An is a beautiful old town.": "../looking-back/audio/cau/e98bb193dd75aa2b.mp3", "Lan sings beautifully, and her voice is beautiful.": "../looking-back/audio/cau/4d5c5951771c97b1.mp3", "A beaver builds its home in the river.": "../skills-2/audio/cau/71eaebe4e33c338d.mp3", "The beaver has strong teeth.": "../skills-2/audio/cau/78b62a6b5ea6b714.mp3", "Beavers cut down trees with their teeth.": "../skills-2/audio/cau/e5e99f9679aaf988.mp3", "Beavers live in Canada.": "../skills-2/audio/cau/a3b3469e1d42a7fe.mp3", "Thank you for being so kind to me.": "../a-closer-look-2/audio/cau/a75c0878deadd1e7.mp3", "Being a doctor is hard, but my aunt is happy.": "../a-closer-look-2/audio/cau/4aa63f5a96fb8206.mp3", "This is the biggest market in the city.": "../a-closer-look-2/audio/cau/ba6358ef44b7b295.mp3", "Ho Chi Minh City is the biggest city in Viet Nam.": "../a-closer-look-2/audio/cau/815c69dda42327e1.mp3", "Mi is wearing a blue dress.": "../a-closer-look-2/audio/cau/992073792364c614.mp3", "The sky is blue, and the sea is dark blue.": "../a-closer-look-2/audio/cau/46190d72fcbbb528.mp3", "Exercise is good for your body.": "../a-closer-look-1/audio/cau/c752373dc0832e44.mp3", "Draw a person and label the parts of the body.": "../a-closer-look-1/audio/cau/136aee3e397e928c.mp3", "She wrote a book about her life.": "../a-closer-look-2/audio/cau/428afa8d58f841a3.mp3", "Lan reads a book every week, so she has many books.": "../a-closer-look-2/audio/cau/5a4070779479f823.mp3", "Birds sit on the branches.": "../skills-2/audio/cau/00bfb45c52a7fb02.mp3", "The bank has many branches.": "../skills-2/audio/cau/17bb6dfdd72e3688.mp3", "In the countryside, we can breathe fresh air.": "../skills-1/audio/cau/a21bd7b3772df526.mp3", "Nam took a deep breath and began to breathe slowly.": "../skills-1/audio/cau/5606af65553e1b1a.mp3", "Big Ben is a famous British landmark.": "../a-closer-look-2/audio/cau/25cdb4cf520b82a1.mp3", "British people often talk about the weather.": "../a-closer-look-2/audio/cau/7c291af5d4779ae9.mp3", "They want to build a new school here.": "../communication/audio/cau/acef8f351c194c82.mp3", "The builder built this house ten years ago.": "../communication/audio/cau/9b9a31fe503b70a0.mp3", "The builders are making a new school.": "../communication/audio/cau/fe7c529c4cac64d6.mp3", "My uncle is a builder.": "../communication/audio/cau/133450a7b43f7adb.mp3", "Butterflies fly among the flowers.": "../looking-back/audio/cau/4afab8d5389e71ca.mp3", "Cuc Phuong is famous for its butterflies.": "../looking-back/audio/cau/3124ab7257fa7073.mp3", "He started a company called Sun Tech.": "../a-closer-look-1/audio/cau/201ec774149f9db7.mp3", "Nam called me last night, and I call him every week.": "../a-closer-look-1/audio/cau/4e3a47db5686e0e1.mp3", "The first iPhone came in 2007.": "audio/cau/b74af45c313ce91a.mp3", "Lan came to my house, and then we went to the park.": "audio/cau/db2ce9de70166e15.mp3", "Mi can swim very well.": "../a-closer-look-1/audio/cau/3e8edac082144330.mp3", "I can ride a bike now, but last year I couldn't.": "../a-closer-look-1/audio/cau/af33705bbc26781d.mp3", "Cars produce carbon dioxide.": "../getting-started/audio/cau/87cd80276e6da6f3.mp3", "We should reduce our carbon footprint.": "../getting-started/audio/cau/7ca016de94230edc.mp3", "Too many cars cause traffic jams.": "../a-closer-look-1/audio/cau/5ac4cbb3cb2d00fb.mp3", "Pollution is a cause of illness and can cause problems.": "../a-closer-look-1/audio/cau/b0502415132a3591.mp3", "Noise causes stress for city people.": "../a-closer-look-1/audio/cau/c4c32fd3a6bdffe8.mp3", "Too much sugar causes health problems.": "../a-closer-look-1/audio/cau/23846d4c8dfddc2f.mp3", "There are many beautiful caves in Hạ Long Bay.": "audio/cau/eadee676fef8f769.mp3", "Some caves are very deep.": "audio/cau/8c0071053712f591.mp3", "We celebrate Tết with our family.": "../a-closer-look-2/audio/cau/e38fba1260dfcaf3.mp3", "Let's celebrate your birthday at home.": "../a-closer-look-2/audio/cau/9e5cefc751ae62b0.mp3", "This pencil costs fifty cents.": "../communication/audio/cau/1734e3bf2ed8e2b9.mp3", "I don't have a cent left.": "../communication/audio/cau/76c07c48ff4ef729.mp3", "There is a community centre in my area.": "../a-closer-look-1/audio/cau/29303f0e938051fb.mp3", "The city centre is busy, and the central park is big.": "../a-closer-look-1/audio/cau/d087f6159981d3e2.mp3", "My bike chain is broken.": "../a-closer-look-1/audio/cau/d415975c511d570d.mp3", "This is a chain of fast food restaurants.": "../a-closer-look-1/audio/cau/c895da38511af5c7.mp3", "One good teacher can change your life.": "../a-closer-look-1/audio/cau/a24566287e5a310e.mp3", "The city changed a lot, and the change is good.": "../a-closer-look-1/audio/cau/c2d3e45906274d36.mp3", "There are forty students in my class.": "../communication/audio/cau/69f347ac209b4fc2.mp3", "Nam is my classmate. We are in the same class.": "../communication/audio/cau/e6a0aa2aaff4be27.mp3", "Việt Nam has a tropical climate.": "../a-closer-look-1/audio/cau/6120a67624262656.mp3", "Climate change is a big problem.": "../a-closer-look-1/audio/cau/bfc6f897b4bf43f6.mp3", "Let's take a closer look at the words.": "audio/cau/3f25d4a7ecb1e46f.mp3", "Lan's house is close, but Mi's house is closer.": "audio/cau/95aeed65b79a000e.mp3", "Lan is my closest friend.": "../a-closer-look-2/audio/cau/ef0ba408fcc399e8.mp3", "Where is the closest bus stop?": "../a-closer-look-2/audio/cau/b7e6a4f0c69a4ff8.mp3", "I join the English club on Fridays.": "../getting-started/audio/cau/4854d8e45991624d.mp3", "Hoa is in the art club at school.": "../getting-started/audio/cau/1bf4d645fed3a1be.mp3", "I came down with a cold last week.": "../a-closer-look-1/audio/cau/6589d8d2056f15e9.mp3", "It is cold in Ha Noi in winter.": "../a-closer-look-1/audio/cau/6af5e5587fe6cf7a.mp3", "My bedroom has colourful walls.": "../a-closer-look-2/audio/cau/5480caf95b688723.mp3", "Each colour is bright, so the picture is colourful.": "../a-closer-look-2/audio/cau/c94ba14044838a90.mp3", "Communication is important in a team.": "audio/cau/ceae7194d8982d8f.mp3", "We communicate in English to improve our communication skills.": "audio/cau/78dbdceb83728ae8.mp3", "The old house is in bad condition.": "audio/cau/9d9ffa685f510da3.mp3", "You can go out on one condition.": "audio/cau/7b86edfe13e3aa0b.mp3", "Living conditions in the city are better.": "../getting-started/audio/cau/f71ddebf2f6ad603.mp3", "The weather conditions are bad today.": "../getting-started/audio/cau/a16e984b4684f780.mp3", "Consider your answer before you speak.": "audio/cau/aa283697b91d51a7.mp3", "We are considering a trip to Huế.": "audio/cau/d54aa62d0d4e182d.mp3", "This bottle contains water.": "../a-closer-look-2/audio/cau/4a7e8cdacc7a4390.mp3", "Fruit contains many vitamins.": "../a-closer-look-2/audio/cau/2e0bf219f8a78164.mp3", "Asia is the largest continent.": "../looking-back/audio/cau/efcdcdf0b347d789.mp3", "Việt Nam is on the Asian continent.": "../looking-back/audio/cau/ebd0485b35dda841.mp3", "There are seven continents in the world.": "../getting-started/audio/cau/48e21b45cd6d6c2c.mp3", "Can you name all the continents?": "../getting-started/audio/cau/6bd107fba2a5c2e0.mp3", "Everyone can contribute to a cleaner city.": "../communication/audio/cau/bd0f3f29c7d7a6a3.mp3", "I contributed some books to the library.": "../communication/audio/cau/99ce6f2122694d1e.mp3", "Thanks for your contribution to the class.": "../communication/audio/cau/add8706ca5dbe82b.mp3", "Every small contribution helps.": "../communication/audio/cau/9f116d17fb766b51.mp3", "Many fish live among the corals.": "audio/cau/6af608c7c1405d58.mp3", "Warm water can kill corals.": "audio/cau/1e80cdfa8389ec03.mp3", "Choose the correct answer A, B or C.": "../a-closer-look-1/audio/cau/6f45c31e9ee537be.mp3", "Nam's answer is correct, but mine is wrong.": "../a-closer-look-1/audio/cau/2f88ef38a2385ee5.mp3", "Sleep is crucial for students.": "../communication/audio/cau/18a2cd663e9f1423.mp3", "This is a crucial match for our team.": "../communication/audio/cau/e537aba4c66178e4.mp3", "Please cut the paper into small pieces.": "../a-closer-look-1/audio/cau/a1fd8b0ff53be3ae.mp3", "Yesterday Nam cut the cake for his friends.": "../a-closer-look-1/audio/cau/97279c7011b57f8b.mp3", "My dad is cutting the grass in the garden.": "../a-closer-look-1/audio/cau/de769b78036d1e0b.mp3", "We are cutting down on plastic bags, and last month we cut down on paper too.": "../a-closer-look-1/audio/cau/9f9ddd6ec177ddbf.mp3", "Hoà Bình Dam makes electricity.": "../skills-2/audio/cau/9cdebec8314b9378.mp3", "Beavers build dams in rivers.": "../skills-2/audio/cau/1af719909f63a275.mp3", "Dams can stop floods.": "../skills-2/audio/cau/986211f25c654b25.mp3", "There are many dams on this river.": "../skills-2/audio/cau/2a6610153a855caf.mp3", "Danger! Do not swim here.": "audio/cau/0afd40ac8685e695.mp3", "These animals are in danger.": "audio/cau/a71ab9ae08dc6654.mp3", "It is dark outside now.": "../a-closer-look-2/audio/cau/48eaca11c1014cbe.mp3", "Minh's room is dark, so he turns on the light.": "../a-closer-look-2/audio/cau/8c6105f992faba73.mp3", "I have English every day.": "../a-closer-look-1/audio/cau/50a9802d88a8dbc0.mp3", "Nam studies by day and sleeps at night.": "../a-closer-look-1/audio/cau/0f498730d8ee8697.mp3", "We saw a deer in the forest.": "../communication/audio/cau/bfed3e84c3c14678.mp3", "There are many deer in the park.": "../communication/audio/cau/245c8bfcea53333a.mp3", "Deforestation causes floods.": "../skills-1/audio/cau/b7ef87be61be28d4.mp3", "We must stop deforestation.": "../skills-1/audio/cau/ef442055a63d4179.mp3", "Our trip depends on the weather.": "audio/cau/f830d432fd192907.mp3", "Children depend on their parents.": "audio/cau/3bae63134e7d207d.mp3", "The Sahara is the largest hot desert.": "../a-closer-look-2/audio/cau/b5ab545ec1917b35.mp3", "Camels can live in the desert.": "../a-closer-look-2/audio/cau/c06453c4acef7e3c.mp3", "The fire destroyed the old house.": "../a-closer-look-1/audio/cau/36cb28d95071f932.mp3", "Pollution destroys the environment.": "../a-closer-look-1/audio/cau/b351f0817a25406e.mp3", "Trees take in carbon dioxide.": "../getting-started/audio/cau/3cd033eccf2546e3.mp3", "What is the distance from your house to school?": "../a-closer-look-1/audio/cau/c31773e8a12f8e54.mp3", "My school is a short distance away, not distant at all.": "../a-closer-look-1/audio/cau/6dcd5ee2374d5448.mp3", "I do my homework after dinner.": "../a-closer-look-1/audio/cau/dfa2558950305f83.mp3", "Phong did his homework, and now it is done.": "../a-closer-look-1/audio/cau/4e496982963ec9df.mp3", "Does Lan like ice cream?": "../a-closer-look-1/audio/cau/15298c934c7dedf6.mp3", "Nam does his homework, but he doesn't watch TV.": "../a-closer-look-1/audio/cau/16100881d98fba74.mp3", "Mi doesn't like milk very much.": "../a-closer-look-1/audio/cau/63a58b0dc618ef2d.mp3", "Nam does his homework, but Minh doesn't do it.": "../a-closer-look-1/audio/cau/362bb11ca0696388.mp3", "I don't like rainy days.": "../communication/audio/cau/111328217b7f4b84.mp3", "We don't play games, but Minh does.": "../communication/audio/cau/851ce9fc9da85e82.mp3", "Please sit down on the chair.": "../a-closer-look-1/audio/cau/08cb6a07df1ed303.mp3", "The cat jumps up and then comes down.": "../a-closer-look-1/audio/cau/009acd9ad7b1a705.mp3", "Do exercise e on page ten.": "../a-closer-look-1/audio/cau/f397a6a2157f10ba.mp3", "The word 'eye' starts with the letter e.": "../a-closer-look-1/audio/cau/5f2132c30b4b4b2f.mp3", "The Earth goes around the Sun.": "../a-closer-look-1/audio/cau/e9deae5a50bf8484.mp3", "We must protect the Earth.": "../a-closer-look-1/audio/cau/c5818b11faf951cb.mp3", "The Earth's surface is mostly water.": "../a-closer-look-1/audio/cau/399c8df06a363890.mp3", "Trees help the Earth's air stay clean.": "../a-closer-look-1/audio/cau/2678850161292d46.mp3", "Cutting trees causes ecological problems.": "../a-closer-look-1/audio/cau/d0a7e57b44380cd9.mp3", "This forest has great ecological value.": "../a-closer-look-1/audio/cau/7546ccc91c254e98.mp3", "We learn about ecology in science class.": "../looking-back/audio/cau/a5d8f301afbb5d9d.mp3", "Pollution damages the ecology of the river.": "../looking-back/audio/cau/dada70e34a99c6b7.mp3", "Tigers are an endangered species.": "../looking-back/audio/cau/b5f8fe7d3b0e436c.mp3", "We must protect endangered animals.": "../looking-back/audio/cau/7096ff6c65a2f11c.mp3", "Solar energy is clean and safe.": "../a-closer-look-1/audio/cau/12d6baefa67435a0.mp3", "Hoa is energetic and full of energy.": "../a-closer-look-1/audio/cau/708c08d09ae44b32.mp3", "We must protect the environment.": "../a-closer-look-1/audio/cau/1116c335bfe25163.mp3", "Plastic waste is a big environmental problem.": "../a-closer-look-1/audio/cau/e0cb17c748b83922.mp3", "Water is essential for life.": "../getting-started/audio/cau/b26018bad059b21c.mp3", "Sleep is essential for students.": "../getting-started/audio/cau/6daf50713525aa39.mp3", "The test was extremely difficult.": "../a-closer-look-1/audio/cau/ccc534030337d3ca.mp3", "I'm extremely happy to see you.": "../a-closer-look-1/audio/cau/6c7b609f63941630.mp3", "Write T for true or F for false.": "../a-closer-look-1/audio/cau/d086c486993b428b.mp3", "Sentence 2 is false, so Nam writes F.": "../a-closer-look-1/audio/cau/87a27d221b2ce0ec.mp3", "Wash your face before breakfast.": "../a-closer-look-1/audio/cau/b40392145a1b9e72.mp3", "Hoa has a round face, and we draw funny faces.": "../a-closer-look-1/audio/cau/bed7bfe736a05e74.mp3", "Smoke from factories makes the air dirty.": "../a-closer-look-1/audio/cau/c81ab4e4468cc59e.mp3", "My uncle works in a shoe factory near Ha Noi.": "../a-closer-look-1/audio/cau/cadf22ae030695ea.mp3", "Is this sentence true or false?": "../getting-started/audio/cau/b08a12186b6dfb5e.mp3", "That answer is false, but Hoa's answer is true.": "../getting-started/audio/cau/493842939182df2a.mp3", "Hoi An is famous for its lanterns.": "../a-closer-look-1/audio/cau/be0831db3c3bf621.mp3", "General Giap became famous, and his fame spread worldwide.": "../a-closer-look-1/audio/cau/4eabd5e77fd10a06.mp3", "My school is not far from my house.": "audio/cau/fa693a015c0f0c90.mp3", "Phong's house is farther from school than mine.": "audio/cau/a8e4b376469602b6.mp3", "My grandparents have a small farm in the countryside.": "../a-closer-look-1/audio/cau/8dfbf1cdb8c722b6.mp3", "The farmer feeds the chickens on his farm.": "../a-closer-look-1/audio/cau/b7fa5397f8451fd9.mp3", "The museum is fascinating.": "../getting-started/audio/cau/6d4f3c452b4f0772.mp3", "He told us a fascinating story.": "../getting-started/audio/cau/7c643802c00a003e.mp3", "Cuc Phuong has rich flora and fauna.": "../a-closer-look-1/audio/cau/87d03299c18782ab.mp3", "We studied the fauna of the island.": "../a-closer-look-1/audio/cau/078d5ba034c4518a.mp3", "My favourite room is the kitchen.": "audio/cau/7fe9b9a43268f379.mp3", "Football is Nam's favourite sport.": "audio/cau/5418f30ef37044b0.mp3", "I feed my cat twice a day.": "../a-closer-look-1/audio/cau/3a8f8f8f00f1daf9.mp3", "Yesterday Lan fed the fish in the pond.": "../a-closer-look-1/audio/cau/01b9c59f1a6a6265.mp3", "I feel happy when I am with my friends.": "../communication/audio/cau/347c7145dbd3848c.mp3", "Nam felt tired after the long trip.": "../communication/audio/cau/722683185c73007a.mp3", "Farmers use fertiliser for their rice.": "../skills-1/audio/cau/846d12ad433609de.mp3", "Too much fertiliser pollutes the water.": "../skills-1/audio/cau/60e780f780ebc4a7.mp3", "Let's watch a film at the cinema tonight.": "audio/cau/b33696a47b363136.mp3", "Nam and Minh watched a funny film last night.": "audio/cau/11db680afca63554.mp3", "We buy fresh fish at the market.": "../communication/audio/cau/1e1bd5d1bfbdcbed.mp3", "Grandpa goes fishing and catches three fish.": "../communication/audio/cau/82e6c573c6d91dda.mp3", "The island has unique flora.": "../a-closer-look-1/audio/cau/2e77145d46a810a2.mp3", "We study the flora of the national park.": "../a-closer-look-1/audio/cau/cce66e7d7b3b5060.mp3", "We need food and water every day.": "../a-closer-look-1/audio/cau/01b6dc39aa643a2b.mp3", "Mum feeds the baby healthy food.": "../a-closer-look-1/audio/cau/1407b84140607171.mp3", "Many animals live in the forest.": "../a-closer-look-1/audio/cau/de5591cef1bfa727.mp3", "We went camping in the forest.": "../a-closer-look-1/audio/cau/81f5245d16792b64.mp3", "We must protect our forests.": "../a-closer-look-1/audio/cau/1e9f9663fa7f3653.mp3", "Forests give us fresh air.": "../a-closer-look-1/audio/cau/4b28416cc0a06737.mp3", "We buy fresh fish and vegetables at the market.": "../a-closer-look-2/audio/cau/61ee9997ca99fa08.mp3", "The air here is fresh, fresher than in the city.": "../a-closer-look-2/audio/cau/04d4e324c4c12ce3.mp3", "Mi and Lan are good friends.": "audio/cau/4315a79df8d3aac1.mp3", "Nam is friendly, so he makes friends easily.": "audio/cau/50b0e863c6e406f4.mp3", "Write short notes, not full sentences.": "../looking-back/audio/cau/14bb97e16bb6d06a.mp3", "The bus was full, but the next one was empty.": "../looking-back/audio/cau/cfd981c78ac3d787.mp3", "My grandmother has a small garden.": "audio/cau/ad0b9ba5604dc0f5.mp3", "Grandpa loves gardening, so our garden is beautiful.": "audio/cau/2afdcb2a5601fa6f.mp3", "We cook with gas at home.": "../getting-started/audio/cau/c0121f13a9efcdb4.mp3", "Cars give off harmful gas.": "../getting-started/audio/cau/831eedff61f28c28.mp3", "Ha Long Bay is famous for its geology.": "../looking-back/audio/cau/1475bc0b974cfbae.mp3", "He studies geology at university.": "../looking-back/audio/cau/1ec7a9913d11c432.mp3", "She gets on well with her neighbours.": "audio/cau/70e1470c821aaa7b.mp3", "It gets cold in winter, and last week it got very cold.": "audio/cau/818ce29897902e0d.mp3", "It's getting dark, so let's go home.": "audio/cau/a5d44c2a5398af17.mp3", "Minh got up late, so he is getting ready quickly.": "audio/cau/be131cb99a335b88.mp3", "The giraffe eats leaves from tall trees.": "audio/cau/27abd057986e2717.mp3", "A giraffe has a very long neck.": "audio/cau/f66bef4ad1527ebf.mp3", "Giraffes are the tallest animals.": "../communication/audio/cau/16f407672a864f9a.mp3", "We fed the giraffes at the safari park.": "../communication/audio/cau/13b2dcdcd1ed2da7.mp3", "Please give me your notebook.": "../a-closer-look-2/audio/cau/63fd3e27b3248933.mp3", "Hoa gives her mum flowers; yesterday she gave her a card.": "../a-closer-look-2/audio/cau/8a999a2635280ba0.mp3", "My teacher gives us a lot of homework.": "../a-closer-look-2/audio/cau/9e792e0228b9fc48.mp3", "Mi always gives good advice, and she gave me some today.": "../a-closer-look-2/audio/cau/9d8952d03493a72d.mp3", "Global warming is a big problem.": "../a-closer-look-1/audio/cau/2517ec4c2b354740.mp3", "English is a global language.": "../a-closer-look-1/audio/cau/ff5af81d904b15f7.mp3", "I go to school by bike.": "../a-closer-look-1/audio/cau/df5dcef1ab40916f.mp3", "We often go to the beach; last summer we went to Nha Trang.": "../communication/audio/cau/9dac5f396b6a209e.mp3", "We are going to visit Hoi An.": "audio/cau/caf0fb980152def1.mp3", "Lan is going to school now; she goes by bus.": "audio/cau/c4af9d8c2b576c6c.mp3", "Nam is good at maths.": "../a-closer-look-1/audio/cau/4fd3587c745c05a2.mp3", "Lan's English is good, but Mi's is better.": "../a-closer-look-1/audio/cau/d371c25a8502dc92.mp3", "Don't walk on the grass.": "../a-closer-look-1/audio/cau/9c3c7d0e34eef719.mp3", "Cows eat grass.": "../a-closer-look-1/audio/cau/10c328a8f63fe6bd.mp3", "Horses run on the grassland.": "../a-closer-look-1/audio/cau/86ed113208c1b60e.mp3", "Mongolia has large grassland.": "../a-closer-look-1/audio/cau/d3b2e65f77e11024.mp3", "Lions live in the African grasslands.": "../a-closer-look-2/audio/cau/50dd36ed22d2a3e1.mp3", "Grasslands are home to many animals.": "../a-closer-look-2/audio/cau/277703103773cb6b.mp3", "That's a great idea for our project!": "../a-closer-look-1/audio/cau/a54aafc7aa505f92.mp3", "We had a great time; the trip was wonderful.": "../a-closer-look-1/audio/cau/3dc3e9c44a5960ce.mp3", "The word 'garden' starts with the letter G.": "../a-closer-look-1/audio/cau/855344adad6266b6.mp3", "Please write a capital G on the board.": "../a-closer-look-1/audio/cau/090b2d929a80461a.mp3", "The forest is the habitat of many birds.": "../a-closer-look-1/audio/cau/edf933ccace12f76.mp3", "Pollution destroys animals' habitats.": "../a-closer-look-1/audio/cau/7ead0876d6149ecb.mp3", "Animals are losing their habitats.": "../a-closer-look-1/audio/cau/b076e5fccde34e18.mp3", "Coral reefs are important habitats.": "../a-closer-look-1/audio/cau/509394b715cd2774.mp3", "Match the first half of the sentence with the second half.": "../a-closer-look-1/audio/cau/e212255b0f113a50.mp3", "Hoa ate half of the cake.": "../a-closer-look-1/audio/cau/6acf1dcf69afd1e6.mp3", "Lan has two brothers.": "../a-closer-look-1/audio/cau/3ee04272e80b66c1.mp3", "Nam has a new bike; he had an old one before.": "../a-closer-look-1/audio/cau/756f69898700b7f4.mp3", "I have a cat and a dog.": "../a-closer-look-1/audio/cau/3942c510ddf250d4.mp3", "We have English today, and we had Maths yesterday.": "../a-closer-look-1/audio/cau/f53b658e1d0dc09e.mp3", "Can you help me with my homework?": "../communication/audio/cau/59064ec1f34486d3.mp3", "Mi is helpful; she always helps her mum cook.": "../communication/audio/cau/82b6e08d58022ab1.mp3", "Everest is the highest mountain in the world.": "../a-closer-look-2/audio/cau/c52c583d53977b9a.mp3", "She got the highest mark in the test.": "../a-closer-look-2/audio/cau/be76ed2a2a659650.mp3", "I go home at five o'clock.": "../communication/audio/cau/a74ab800c921a80b.mp3", "After school, Mi does her homework at home.": "../communication/audio/cau/ecaf6456acc0b85d.mp3", "In the hot sun, he is always at the school gate.": "../a-closer-look-2/audio/cau/d94f7911dc61672f.mp3", "The heat is terrible today; it's so hot!": "../a-closer-look-2/audio/cau/15a129bda3aabffd.mp3", "Our house is near the river.": "../a-closer-look-1/audio/cau/462620c6e9d42610.mp3", "Lan's house is big, so the housework takes a long time.": "../a-closer-look-1/audio/cau/ffae3b516fc16794.mp3", "How did he become a famous doctor?": "../communication/audio/cau/0acfb865542d1705.mp3", "How old is Minh, and how does he go to school?": "../communication/audio/cau/0d6be1faa0d18a2b.mp3", "He was poor. However, he never gave up.": "../a-closer-look-1/audio/cau/893555bad2aff789.mp3", "It rained. However, Nam still went to school, but late.": "../a-closer-look-1/audio/cau/97115d20f691f7e4.mp3", "Humans need clean air to live.": "../a-closer-look-1/audio/cau/67a9e9c7f01587d9.mp3", "Dogs are good friends of humans.": "../a-closer-look-1/audio/cau/b65c07750384a494.mp3", "Lions hunt zebras.": "../a-closer-look-1/audio/cau/e979d5c6712e318e.mp3", "People should not hunt rare animals.": "../a-closer-look-1/audio/cau/080e073df34bf4c3.mp3", "Hunting is banned in national parks.": "../a-closer-look-1/audio/cau/42ebecd645773fc6.mp3", "Hunting makes some animals disappear.": "../a-closer-look-1/audio/cau/dd45a1243f2e6f35.mp3", "Nam and Ba are eating ice cream.": "../a-closer-look-2/audio/cau/8187b98018baa52e.mp3", "Please put some ice in my drink.": "../a-closer-look-2/audio/cau/728830e39b5e64bd.mp3", "The roads are icy in winter.": "../a-closer-look-1/audio/cau/0ea1d08b999f6659.mp3", "An icy wind blew from the north.": "../a-closer-look-1/audio/cau/37ab9e9f61657dcc.mp3", "It is important to keep our streets clean.": "../a-closer-look-1/audio/cau/4541b30fbeb1b8aa.mp3", "Reading is important; never forget its importance.": "../a-closer-look-1/audio/cau/0b2b91b8a69bb8c9.mp3", "We should improve the parks in our neighbourhood.": "../skills-1/audio/cau/ebaf5139cac32473.mp3", "Read every day to improve, and you'll see improvement.": "../skills-1/audio/cau/5917f2ebe74764c5.mp3", "The plan should include more green spaces.": "../a-closer-look-2/audio/cau/3a7e33a5edc71898.mp3", "Does the ticket include lunch, including drinks?": "../a-closer-look-2/audio/cau/9c4f367cc3548964.mp3", "After 'How about', we use the verb with -ing.": "../a-closer-look-1/audio/cau/0b5b2f5d668491cd.mp3", "How about buying a new lamp for your bedroom?": "../a-closer-look-1/audio/cau/55a020c7bbf1ac54.mp3", "My school is big and beautiful.": "../a-closer-look-1/audio/cau/d5765e25cafa0eea.mp3", "Today it is sunny, but yesterday it was rainy.": "../a-closer-look-1/audio/cau/ed1bcaf6501bfd0c.mp3", "Ha Long Bay has thousands of islands.": "../a-closer-look-2/audio/cau/be29ea69596d6ca9.mp3", "Viet Nam has many beautiful islands.": "../a-closer-look-2/audio/cau/8ff775d4440744df.mp3", "We were late because of a traffic jam.": "../a-closer-look-2/audio/cau/e56d04589badd4a4.mp3", "There is a jam on Le Loi Street, so the roads are jammed.": "../a-closer-look-2/audio/cau/927ab8d456162167.mp3", "We're playing badminton. Do you want to join us, Hoa?": "audio/cau/463866c7dddbef43.mp3", "Nam joined the school football club last year.": "audio/cau/706eaa16ea8a910a.mp3", "We should keep our streets clean.": "../a-closer-look-1/audio/cau/3f2dd8440f55f148.mp3", "Lan kept her old toys, and she still keeps them.": "../a-closer-look-1/audio/cau/d20c525ce8b90756.mp3", "The lake is five kilometres from my house.": "audio/cau/a12e5758398f97a7.mp3", "It's one kilometre to school, so I walk.": "audio/cau/a2edc851330c0b0e.mp3", "Nguyen Hue Street is 1 km from Binh's house.": "../a-closer-look-2/audio/cau/227eb730489c05b8.mp3", "The lake is 5 km away, so we go by bus.": "../a-closer-look-2/audio/cau/3ab53a0753e4fdbc.mp3", "Do you know his life story?": "../a-closer-look-2/audio/cau/db0ea43493818ad0.mp3", "I know her well; I knew her at primary school.": "../a-closer-look-2/audio/cau/26baffaf9e8a0ddb.mp3", "The word 'lamp' starts with the letter l.": "../a-closer-look-1/audio/cau/c5e08a5413a4f66b.mp3", "Please write a capital L on the board.": "../a-closer-look-1/audio/cau/63173cda63a08912.mp3", "Hoan Kiem Lake is in the centre of Ha Noi.": "../a-closer-look-1/audio/cau/98e7edb5d4146709.mp3", "We walk around the lake every morning.": "../a-closer-look-1/audio/cau/f01b3e2f8bffaa21.mp3", "A valley is a kind of landform.": "../communication/audio/cau/bc24b3dcd5af03cd.mp3", "What landform is near your town?": "../communication/audio/cau/1f6131de244890dd.mp3", "Mountains and rivers are landforms.": "../a-closer-look-2/audio/cau/b88489468004dd17.mp3", "Viet Nam has many different landforms.": "../a-closer-look-2/audio/cau/e3ceccd21d22be26.mp3", "Son Doong is the largest cave in the world.": "../a-closer-look-2/audio/cau/e24701bf03dbe79b.mp3", "Ho Chi Minh City is the largest city in Viet Nam.": "../a-closer-look-2/audio/cau/846e9ffebe286bac.mp3", "I visited my grandparents last weekend.": "../a-closer-look-1/audio/cau/553e8bea75bbdbbd.mp3", "Last Sunday was fun, and next Sunday will be fun too.": "../a-closer-look-1/audio/cau/17be93822cc3c397.mp3", "I learnt a new song today.": "../a-closer-look-1/audio/cau/002dc8ba978f437b.mp3", "Mi likes to learn new words; yesterday she learnt ten.": "../a-closer-look-1/audio/cau/01afc6c13b541caf.mp3", "He had a difficult life when he was young.": "../a-closer-look-1/audio/cau/0e2c7b87c896e8b7.mp3", "City life is busy, and people live very fast.": "../a-closer-look-1/audio/cau/c7a56b97906b19d2.mp3", "Stop when the traffic light is red.": "../a-closer-look-2/audio/cau/dd4921089bcbaa08.mp3", "Turn on the light, please; the room is dark.": "../a-closer-look-2/audio/cau/dd20920a13027c13.mp3", "I like noodles very much.": "../a-closer-look-2/audio/cau/7557928354c11c4a.mp3", "I like cats, but I dislike spiders.": "../a-closer-look-2/audio/cau/bdd9c25c87fbc823.mp3", "Water is a liquid.": "../getting-started/audio/cau/22fdbf48b3ade6dc.mp3", "Drink lots of liquids when you are ill.": "../getting-started/audio/cau/e57ed101e18e3f1b.mp3", "My little brother is five years old.": "../a-closer-look-2/audio/cau/e22af4e6bb3d77f0.mp3", "I have a little money, but my sister has less.": "../a-closer-look-2/audio/cau/520fdc680c743ed9.mp3", "We live in a small village.": "../a-closer-look-1/audio/cau/8438d091662da029.mp3", "My grandparents live in the countryside and have a happy life.": "../a-closer-look-1/audio/cau/a21ec63c6b42bc8d.mp3", "My grandparents raise livestock in the countryside.": "../communication/audio/cau/84e1aa1ccd25a0cc.mp3", "The farmers feed their livestock every morning.": "../communication/audio/cau/4510677c9760017b.mp3", "There is a big sofa in the living room.": "../a-closer-look-1/audio/cau/85ee341c5ccef3a3.mp3", "We live in a small house with a nice living room.": "../a-closer-look-1/audio/cau/a4537e161135cc8a.mp3", "Bat Trang pottery is a famous local product.": "../a-closer-look-1/audio/cau/ea08f150b9375ac4.mp3", "Many locals buy food from local farmers at the market.": "../a-closer-look-1/audio/cau/dfc3f008f3837ff1.mp3", "The Mekong is a very long river.": "../a-closer-look-2/audio/cau/962b2d2abaecb121.mp3", "Mi has long hair, but Lan has short hair.": "../a-closer-look-2/audio/cau/21e34cbfd1358b0e.mp3", "Look at the board, please.": "../getting-started/audio/cau/512572a71fea8cfe.mp3", "Look at Minh! He is very good-looking today.": "../getting-started/audio/cau/3a8f3a88e8a3813b.mp3", "Mi is looking for her notebook in the bedroom.": "../getting-started/audio/cau/9cf0853b1a840504.mp3", "Look! Nam is looking at the picture on the wall.": "../getting-started/audio/cau/debf12a72a75e3eb.mp3", "Mi looks happy today.": "../getting-started/audio/cau/d53ae1b2afc27fcb.mp3", "Look at Nam; he looks tired.": "../getting-started/audio/cau/b6b16cdb7526bf98.mp3", "With a plan, Lan is never at a loss with too much work.": "../a-closer-look-1/audio/cau/bb851d51c8b95d7d.mp3", "Nam was at a loss when all his tests came at once.": "../a-closer-look-1/audio/cau/8f5192fc719bd367.mp3", "I love my family.": "../a-closer-look-2/audio/cau/02c5061798cc56cc.mp3", "My grandma is loving, and I love her a lot.": "../a-closer-look-2/audio/cau/588e4f5967e2076b.mp3", "Mai loves reading comic books.": "audio/cau/d1b2f4b3c981705e.mp3", "Hoa loves her lovely little cat.": "audio/cau/8facc28663ba700c.mp3", "Fresh air is good for your lungs.": "../communication/audio/cau/19abe62be6bd964e.mp3", "Dirty air can hurt our lungs.": "../communication/audio/cau/2144514191c41a6c.mp3", "The main problem in the city is traffic.": "../a-closer-look-2/audio/cau/5de5106d00321b17.mp3", "The main roads are busy, mainly in the morning.": "../a-closer-look-2/audio/cau/8298c8b4a3e2e8a4.mp3", "Hard work can make your dreams come true.": "../a-closer-look-1/audio/cau/b31d6220b696ab85.mp3", "He made many mistakes, but he learnt to make good choices.": "../a-closer-look-1/audio/cau/f95abe45aba09ae8.mp3", "Maths is my favourite subject.": "audio/cau/c4dbac3c27e1034e.mp3", "Mathematics, or maths, is hard but fun.": "audio/cau/6ffbed30122c7baa.mp3", "Germs are microscopic.": "../communication/audio/cau/f164f733853c12a8.mp3", "We can't see microscopic animals with our eyes.": "../communication/audio/cau/021098040d21efe2.mp3", "Keep your goal in mind and work hard.": "audio/cau/d67edfb408f8ae2b.mp3", "Lan changed her mind and decided to become a doctor.": "audio/cau/24e15176df525aa5.mp3", "She saved money to buy a new bike.": "audio/cau/47b199504b22fee6.mp3", "Don't waste money; save some money every month.": "audio/cau/6545086d5613a2d1.mp3", "The monkeys are eating bananas.": "../looking-back/audio/cau/f79caf5f2981e2e7.mp3", "We saw monkeys at the zoo.": "../looking-back/audio/cau/b5724a3c92e02bae.mp3", "My birthday is next month.": "audio/cau/d797fe70f9bb3ff4.mp3", "We have a monthly test, so there is one test every month.": "audio/cau/9d545a2d1d2657a1.mp3", "The moon is very bright tonight.": "../a-closer-look-1/audio/cau/02e56f03f332b839.mp3", "Children look at the moon at Mid-Autumn.": "../a-closer-look-1/audio/cau/fd329d437dfe6d36.mp3", "My mother is a nurse.": "../a-closer-look-1/audio/cau/7504a7ce3f463355.mp3", "Mi's mother, her mum, cooks very well.": "../a-closer-look-1/audio/cau/4860342249a4a0b1.mp3", "We climbed the mountain on Sunday.": "../a-closer-look-2/audio/cau/3540fe0a0191a696.mp3", "There is snow on the mountain.": "../a-closer-look-2/audio/cau/d6fce88f07e19286.mp3", "Mr Nam is our English teacher.": "../a-closer-look-2/audio/cau/38bbba50eac133a3.mp3", "Mr Minh and Ms Lan work at my school.": "../a-closer-look-2/audio/cau/22a842da4f6100e9.mp3", "She won a national prize in maths.": "../a-closer-look-1/audio/cau/6a93b9368e7abe3a.mp3", "Our nation has many national heroes.": "../a-closer-look-1/audio/cau/fe097f04f907a2a9.mp3", "Ha Long Bay is a natural wonder.": "../a-closer-look-1/audio/cau/090f3246ac97d064.mp3", "We should use natural light.": "../a-closer-look-1/audio/cau/6a5bbb9647fc89e3.mp3", "We should protect nature.": "../a-closer-look-1/audio/cau/43fd6f1ae36eca76.mp3", "I love the beauty of nature.": "../a-closer-look-1/audio/cau/0044999cd3572ec0.mp3", "We need more parks in the city.": "../skills-2/audio/cau/fa790aed3aa20742.mp3", "Plants need water, and Mi needs some help.": "../skills-2/audio/cau/43af483482c3e17f.mp3", "See you next week!": "../a-closer-look-1/audio/cau/e955abbc627cb84b.mp3", "Last week we had a test, and next week we have a trip.": "../a-closer-look-1/audio/cau/e51bba1694cc9fe2.mp3", "Ha Noi is in the north of Viet Nam.": "../a-closer-look-1/audio/cau/5af5919b198f2d46.mp3", "The wind comes from the north.": "../a-closer-look-1/audio/cau/d039649b93012564.mp3", "She did not give up her dream.": "../a-closer-look-1/audio/cau/b5d39e3052bc5fbb.mp3", "I am not tired, and I'm not hungry.": "../a-closer-look-1/audio/cau/9485504d93b05a38.mp3", "I am doing my homework now.": "audio/cau/c512289bbb165978.mp3", "It is raining now, so we stay at home.": "audio/cau/ac1b5a1cae28deb6.mp3", "We observe the stars at night.": "../getting-started/audio/cau/53df437b829c1718.mp3", "Observe the picture and answer.": "../getting-started/audio/cau/92509b0a410a5f4d.mp3", "The Pacific Ocean is the biggest ocean.": "../a-closer-look-1/audio/cau/3173e229089548be.mp3", "Plastic waste goes into the sea and then the ocean.": "../a-closer-look-1/audio/cau/7d40b32c72996455.mp3", "A: I'm sorry I'm late. B: That's OK.": "../communication/audio/cau/1bbe28ae96b898d1.mp3", "Are you OK? You look tired.": "../communication/audio/cau/26aa4543d75a47ea.mp3", "My grandfather is seventy years old.": "../looking-back/audio/cau/ad4ec0973ce447a3.mp3", "My bike is old, but my sister's bike is new.": "../looking-back/audio/cau/dc292ece9d402a3f.mp3", "This is the oldest pagoda in Ha Noi.": "../communication/audio/cau/112d241056ccf384.mp3", "My grandpa is the oldest in my family.": "../communication/audio/cau/9f9847641a26a88e.mp3", "There is only one bed in my bedroom.": "../a-closer-look-2/audio/cau/000e91b12face3a4.mp3", "Lan is an only child; she has just one cousin.": "../a-closer-look-2/audio/cau/b6ec9a93c21bdf30.mp3", "Mi went out with her friends last night.": "../a-closer-look-1/audio/cau/6662db3eac9ce4e0.mp3", "Nam wants to find out more about his grandfather's life.": "../a-closer-look-1/audio/cau/c2c4b3120ecb6468.mp3", "Astronauts travel into outer space.": "../getting-started/audio/cau/200be72359f766d7.mp3", "Remove the outer skin of the onion.": "../getting-started/audio/cau/e1f17ee1d8431963.mp3", "Trees give us oxygen.": "../a-closer-look-1/audio/cau/2bd40904960aaa48.mp3", "There is no oxygen on the Moon.": "../a-closer-look-1/audio/cau/c0602a9f0ae0546a.mp3", "This is the Panda Room.": "../a-closer-look-1/audio/cau/6da2c54e49159886.mp3", "The panda is eating bamboo.": "../a-closer-look-1/audio/cau/c7f10d77305d79dd.mp3", "Read the first paragraph and answer the question.": "../skills-1/audio/cau/43e8d58106b6726a.mp3", "Write a short paragraph of about 80 words.": "../skills-1/audio/cau/79fc537e0a2633c9.mp3", "We often play in the park after school.": "../a-closer-look-2/audio/cau/8d37e1ca664dbf08.mp3", "Dad parks his motorbike near the park gate.": "../a-closer-look-2/audio/cau/54a831b26aaf5a2e.mp3", "A penguin can swim very fast.": "../communication/audio/cau/2f4313ba21a61732.mp3", "The penguin lives in the Antarctic.": "../communication/audio/cau/c54ae850a91d0db8.mp3", "Penguins can't fly.": "../communication/audio/cau/387778795fb1a00c.mp3", "We saw penguins at the aquarium.": "../communication/audio/cau/dc94901ebe1d7da9.mp3", "There are five people in my family.": "../a-closer-look-2/audio/cau/61d24a117613907d.mp3", "One person is late, but the other people are here.": "../a-closer-look-2/audio/cau/b4e5b7ba18b09096.mp3", "The police protect people's lives and property.": "../skills-1/audio/cau/a0a5f9e15b6f2ecc.mp3", "Each person has a dream, and people's dreams are different.": "../skills-1/audio/cau/5ac1723fa647cbb7.mp3", "Farmers use pesticide on their crops.": "../skills-2/audio/cau/57f6277700a157d1.mp3", "Too much pesticide is bad for the soil.": "../skills-2/audio/cau/e9e11633407a4002.mp3", "Pesticides can pollute rivers.": "../skills-2/audio/cau/ec9695ac603d43a7.mp3", "We grow vegetables without pesticides.": "../skills-2/audio/cau/edf776cb5333d13b.mp3", "Earth is our planet.": "../a-closer-look-1/audio/cau/6f7b3ecf5f2930a7.mp3", "Mars is a red planet.": "../a-closer-look-1/audio/cau/0de5bbb6c6f0ac63.mp3", "There are eight planets in our solar system.": "../getting-started/audio/cau/328a5da77f597743.mp3", "Which planets are near the Sun?": "../getting-started/audio/cau/41cfd8e529faefbe.mp3", "There is a plant next to the window.": "../a-closer-look-1/audio/cau/ead07f80a6f49805.mp3", "Mi plants flowers and waters the plants every day.": "../a-closer-look-1/audio/cau/8379ade47936222a.mp3", "Plants need water and sunlight.": "../a-closer-look-1/audio/cau/e6bc337addd58412.mp3", "People make com from young rice plants.": "../a-closer-look-1/audio/cau/5ab8c23c4ad5e1eb.mp3", "We should use less plastic.": "audio/cau/6086cc4fcde84c05.mp3", "Bring a cloth bag instead of a plastic bag.": "audio/cau/9da1cfd8517ef4f4.mp3", "Polar bears live in very cold places.": "../a-closer-look-2/audio/cau/9036c2a5ba8ce9d8.mp3", "The polar ice is melting.": "../a-closer-look-2/audio/cau/32824820c7a2b7d0.mp3", "It is very cold at the North Pole.": "../a-closer-look-1/audio/cau/55c1f8cbfb3ddf32.mp3", "The flag is on a tall pole.": "../a-closer-look-1/audio/cau/eb82a3d3eae0dd7a.mp3", "The Earth has two poles.": "../a-closer-look-1/audio/cau/0736a1421f09407d.mp3", "They put up the tent with two poles.": "../a-closer-look-1/audio/cau/70dedd29cbf34003.mp3", "Our school has a no-plastic policy.": "../skills-1/audio/cau/663ee2353a73ee17.mp3", "This is a new policy.": "../skills-1/audio/cau/f1d285b2fe4201cb.mp3", "Factories pollute the river.": "../a-closer-look-1/audio/cau/2157f7ac9f788df5.mp3", "Don't pollute the beach.": "../a-closer-look-1/audio/cau/13ed1940cd163a96.mp3", "The air in big cities is often polluted.": "../a-closer-look-1/audio/cau/3f2265c1134300cf.mp3", "Traffic causes air pollution, so the city is polluted.": "../a-closer-look-1/audio/cau/41cbf08c31632fed.mp3", "Noise pollution is a big problem in the city.": "../a-closer-look-1/audio/cau/6f7de550e9658c27.mp3", "Factories pollute the river, so the water is polluted.": "../a-closer-look-1/audio/cau/b4e816708b260a17.mp3", "There are fish in the pond.": "../skills-2/audio/cau/cf5211930ec6af27.mp3", "Ducks swim in the pond.": "../skills-2/audio/cau/0e2b6080faca513e.mp3", "The village has many ponds.": "../looking-back/audio/cau/a6b523dcf5e777ac.mp3", "Frogs live in ponds.": "../looking-back/audio/cau/be58911c5a3ea4ff.mp3", "We must preserve our traditional crafts.": "../a-closer-look-1/audio/cau/4151c066363a5208.mp3", "The village works hard to protect and preserve its old houses.": "../a-closer-look-1/audio/cau/2efd6ae0e9834fdb.mp3", "Mice are prey for cats.": "../skills-1/audio/cau/00bf27141cb278e2.mp3", "The eagle caught its prey.": "../skills-1/audio/cau/b582cd1aaf3e29ee.mp3", "Vietnam produces a lot of rice.": "../communication/audio/cau/c83e7439f3ddce04.mp3", "Cows produce milk.": "../communication/audio/cau/d7aa498fed97c70f.mp3", "We should protect the environment.": "../a-closer-look-1/audio/cau/b90a58bb2e782cd1.mp3", "A helmet gives you protection on the road.": "../a-closer-look-1/audio/cau/20e1fdaea6d0589e.mp3", "The school provides free lunch.": "../a-closer-look-1/audio/cau/1f694f01addd8209.mp3", "Trees provide shade.": "../a-closer-look-1/audio/cau/c989999ea62ae048.mp3", "The teacher asks us three questions.": "../getting-started/audio/cau/9e7c27a7a37e13a0.mp3", "Read the questions carefully and write your answers.": "../getting-started/audio/cau/7fcc03272c2a6124.mp3", "The radius of this circle is 5 cm.": "../a-closer-look-2/audio/cau/cb2bb4fd573a4cd1.mp3", "There are three shops within a radius of 1 km.": "../a-closer-look-2/audio/cau/7923528aebdd0168.mp3", "The rain helps the plants grow.": "../looking-back/audio/cau/dcb6145c778bef36.mp3", "It is rainy today, so take an umbrella.": "../looking-back/audio/cau/10a2647a630c9236.mp3", "The Amazon is a huge rainforest.": "../a-closer-look-2/audio/cau/a16043034f89a016.mp3", "Many animals live in the rainforest.": "../a-closer-look-2/audio/cau/d8850a414c6ee2a5.mp3", "Raise your hand if you know the answer.": "../a-closer-look-1/audio/cau/70fad8908990bbee.mp3", "We raised money for poor children.": "../skills-1/audio/cau/a223523773414bf3.mp3", "I read a book before bed every night.": "../communication/audio/cau/52f4120305948c56.mp3", "Yesterday Mi read a story, because reading is her hobby.": "../communication/audio/cau/a206c7fecbd29a47.mp3", "Reading helps us learn new words.": "../communication/audio/cau/a36b0142402545f6.mp3", "I read a story last night, and it was great.": "../communication/audio/cau/67941e0da7d7be3c.mp3", "My grandfather reads the newspaper every morning.": "audio/cau/4ac9114ced89b05c.mp3", "Phong is a good reader; he reads two books a week.": "audio/cau/2e1abd5154711531.mp3", "My new friend is really kind.": "../communication/audio/cau/abe28633dc1304c0.mp3", "Is this a real photo? Yes, it's really from Ha Long Bay.": "../communication/audio/cau/a28021fb9066cf49.mp3", "Lan is wearing a red dress.": "../a-closer-look-2/audio/cau/ae3c1aa62302c501.mp3", "The sky is reddish at sunset, and the sun is red.": "../a-closer-look-2/audio/cau/6fcd7d055aec1d60.mp3", "What does the word 'it' refer to?": "../communication/audio/cau/8f818ab4263b2f9b.mp3", "In this sentence, 'they' refers to the students.": "../communication/audio/cau/4be6bd265043144d.mp3", "Vietnam has three main regions.": "../a-closer-look-1/audio/cau/4302ee1efef800fc.mp3", "Some regions have no rain for months.": "../a-closer-look-1/audio/cau/cd2edcdb20657cf7.mp3", "They released the turtles into the sea.": "../skills-1/audio/cau/db3b06d89a8d6c83.mp3", "The band will release a new song.": "../skills-1/audio/cau/5195f5bec431da0e.mp3", "Firefighters rescued the cat.": "audio/cau/edfba8d6aa9c2f03.mp3", "They rescue people from floods.": "audio/cau/7487c11515484adc.mp3", "Cuc Phuong is a nature reserve.": "../a-closer-look-1/audio/cau/252eaeb240c00c29.mp3", "I reserved a table for four.": "../a-closer-look-1/audio/cau/c2a35b371b2c0c2c.mp3", "Vietnam has many nature reserves.": "../a-closer-look-1/audio/cau/6824092eb7193af7.mp3", "Oil reserves will run out one day.": "../a-closer-look-1/audio/cau/4e77893a1645d993.mp3", "The residents keep the street clean.": "../communication/audio/cau/09ae4d417399b3fd.mp3", "He is a resident of Da Nang.": "../communication/audio/cau/5cc139efa56b9f77.mp3", "He is a rich man.": "../a-closer-look-1/audio/cau/94ae2901b2b5cb7b.mp3", "Vietnam has a rich culture.": "../a-closer-look-1/audio/cau/549692b165e5c98f.mp3", "My aunt's house is near the river.": "../a-closer-look-1/audio/cau/a6e8ddca094f143a.mp3", "We swim in the river in summer.": "../a-closer-look-1/audio/cau/ad856ac1e2451519.mp3", "The path is rocky.": "../a-closer-look-2/audio/cau/f20b31f2d668a246.mp3", "We walked along the rocky beach.": "../a-closer-look-2/audio/cau/aeeba6851d36d2f5.mp3", "Our house has a red roof.": "../a-closer-look-2/audio/cau/963b55ff22ec5b2d.mp3", "Many roofs in my village are red.": "../a-closer-look-2/audio/cau/697d0779140adeaa.mp3", "Please put your rubbish in the bin.": "audio/cau/3797d15061da27bc.mp3", "Nam picks up litter and other rubbish in the park.": "audio/cau/2004fa74d47adf15.mp3", "She's my best friend in class 6A.": "../a-closer-look-1/audio/cau/810592fcf73e04e7.mp3", "This is Vinh's bike, and he's in my class.": "../a-closer-look-1/audio/cau/6a8b8131a5222edf.mp3", "I said, can you pass me the book?": "../a-closer-look-2/audio/cau/e2db7c41d720581d.mp3", "The teacher said we should sleep early.": "../a-closer-look-2/audio/cau/f9528b768b823292.mp3", "The satellite sends pictures back to Earth.": "../a-closer-look-2/audio/cau/3341edb677e334af.mp3", "Viet Nam has sent some satellites into space.": "../a-closer-look-2/audio/cau/9f74eb1bc264497e.mp3", "Firefighters save people from burning buildings.": "audio/cau/455006b1a6cd17b8.mp3", "Lan saves money and keeps her savings in a box.": "audio/cau/cd1cde14a55133aa.mp3", "I saw a beautiful rainbow yesterday afternoon.": "../skills-2/audio/cau/87d8e8a9aa1c8cb1.mp3", "We saw many animals at the zoo.": "../skills-2/audio/cau/bf15ca1e43e22b9a.mp3", "I put my books in my schoolbag before school.": "../a-closer-look-1/audio/cau/c492164eb59da7f4.mp3", "The due date for our science project is next Monday.": "../getting-started/audio/cau/bb87c23f8f64cbc9.mp3", "Minh enjoys science lessons.": "../getting-started/audio/cau/b15b6103dc344829.mp3", "I want to be a scientist in the future.": "../getting-started/audio/cau/56f590dac1d44659.mp3", "The scientist works in a big laboratory.": "../getting-started/audio/cau/07462f048de340a2.mp3", "My grandparents' house is near the sea.": "../a-closer-look-1/audio/cau/acd2af1fe0d48aed.mp3", "We swim in the sea in summer.": "../a-closer-look-1/audio/cau/a658c72373cebc53.mp3", "We watched the seals at the aquarium.": "../a-closer-look-2/audio/cau/c44be086a687fff1.mp3", "Baby seals have soft white fur.": "../a-closer-look-2/audio/cau/c4572e5442fc7309.mp3", "Write a sentence about your family.": "../a-closer-look-1/audio/cau/9ffdb94eb27ae024.mp3", "This sentence is short and easy to read.": "../a-closer-look-1/audio/cau/f99b7a9b5f47ebe1.mp3", "You should eat more vegetables.": "../a-closer-look-2/audio/cau/d3873c12c668ddab.mp3", "We should recycle, and we shouldn't waste water.": "../a-closer-look-2/audio/cau/bdd4848df2193265.mp3", "We learn about the significance of Tet.": "../skills-1/audio/cau/8323b23bde2a71f3.mp3", "This temple has great historical significance.": "../skills-1/audio/cau/bbeb9d69f95f1bc1.mp3", "Life in my city is similar to life in yours.": "../a-closer-look-2/audio/cau/b89b4fb5bd2e62ee.mp3", "Hoa and Lan look similar, but their hobbies are different.": "../a-closer-look-2/audio/cau/612906abb392c0a7.mp3", "We learn new skills at the English club.": "audio/cau/84d5837cc14182f6.mp3", "Listening is an important skill, and speaking skills are useful too.": "audio/cau/18ae79d29069fa38.mp3", "My house is small but cosy.": "../a-closer-look-2/audio/cau/361843b6d8177bed.mp3", "I live in a small flat, not a big house.": "../a-closer-look-2/audio/cau/e341afdae498f225.mp3", "The street is smoky because of the traffic smoke.": "../getting-started/audio/cau/00cf364f4119ec19.mp3", "I'm so pleased you won the prize!": "../skills-2/audio/cau/345d567c5208a7af.mp3", "It was raining, so we stayed at home.": "../skills-2/audio/cau/d3e8c1c4c40bf63a.mp3", "Our school uses solar energy.": "../a-closer-look-2/audio/cau/3476b577322e35b6.mp3", "They put solar panels on the roof.": "../a-closer-look-2/audio/cau/bdd8437542acf3b5.mp3", "Ca Mau is in the south of Viet Nam.": "../a-closer-look-1/audio/cau/335ef32087970e22.mp3", "Birds fly south in winter.": "../a-closer-look-1/audio/cau/a86decadd15ceb46.mp3", "Our city needs more space for parks.": "../getting-started/audio/cau/4789110f4d6851be.mp3", "The new flat is spacious, with lots of space.": "../getting-started/audio/cau/9028743b09798c85.mp3", "Tet is a special time for Vietnamese families.": "../communication/audio/cau/5f60a4fd69577fbf.mp3", "Com is a speciality of Ha Noi, and it's very special.": "../communication/audio/cau/d7109b486b9421a3.mp3", "Many species of birds live in this forest.": "../communication/audio/cau/40739fc6238bf54e.mp3", "The tiger is an endangered species.": "../communication/audio/cau/251cfcced2d6ca89.mp3", "I can see a bright star in the sky.": "audio/cau/2be5fc060ccf7433.mp3", "It was a starry night, and Lan counted every star.": "audio/cau/b3f87b1132973e52.mp3", "My grandfather started work when he was fifteen.": "audio/cau/9cd956a07a50d11d.mp3", "The film started at seven and finished at nine.": "audio/cau/7b234820845db47a.mp3", "Please stop talking and listen to me.": "../skills-1/audio/cau/14d99e9f18d5a441.mp3", "The bus will stop here and then start again.": "../skills-1/audio/cau/2af4e67bdadcfda0.mp3", "Each student has a book, and all the students love our teacher.": "../getting-started/audio/cau/04de8679f0e55800.mp3", "Mi studies English every evening.": "../a-closer-look-1/audio/cau/b1218f9b9530760b.mp3", "Nam studied hard last year, and now he studies even harder.": "../a-closer-look-1/audio/cau/9817881934cebf3a.mp3", "The sun rises early in summer.": "../a-closer-look-1/audio/cau/f4f11748f6c98beb.mp3", "It is sunny today, so we can play in the sun.": "../a-closer-look-1/audio/cau/257c0e37b623b01d.mp3", "The surface of the table is smooth.": "../a-closer-look-2/audio/cau/48619e4b94e3fa7b.mp3", "Leaves float on the surface of the water.": "../a-closer-look-2/audio/cau/162f288edb0fd3d2.mp3", "Our city needs a better public transport system.": "../a-closer-look-2/audio/cau/b1069c0dd3655b53.mp3", "The metro system makes travel in the city easier.": "../a-closer-look-2/audio/cau/523f0c64c38a2327.mp3", "In \"don't\", the letter t comes from not.": "../a-closer-look-1/audio/cau/549e7bc5a2456c75.mp3", "I didn't go out because I was tired.": "../a-closer-look-1/audio/cau/5cc7479c1b749e64.mp3", "I talked with Lan about her well-balanced life.": "../skills-2/audio/cau/02abb2e169d7ed5a.mp3", "Minh talked to his teacher after class.": "../skills-2/audio/cau/54a184a8293b18ef.mp3", "My father is very tall.": "../a-closer-look-2/audio/cau/fbbb73825cd6c0b9.mp3", "Minh is tall, but Phong is short.": "../a-closer-look-2/audio/cau/dc16694351cdb299.mp3", "Our English teacher is very kind.": "../a-closer-look-1/audio/cau/4869000a32bce322.mp3", "Ms Hoa taught us maths last year; she is a great teacher.": "../a-closer-look-1/audio/cau/01cfa396481f53ff.mp3", "The UK has a temperate climate.": "../communication/audio/cau/b459c922fe9e98a5.mp3", "Many apple trees grow in temperate areas.": "../communication/audio/cau/55a71912f831b9b9.mp3", "The temperature today is 35 degrees.": "../a-closer-look-1/audio/cau/4ccb7417e160f652.mp3", "The nurse took my temperature.": "../a-closer-look-1/audio/cau/2792d455a023f825.mp3", "There is a big garden in my house.": "../communication/audio/cau/94db3c106fafa1ac.mp3", "Your bag is here, and my bag is over there.": "../communication/audio/cau/37204e4c7e951d02.mp3", "I think he is a great person.": "../communication/audio/cau/9ae2e70b49a3159f.mp3", "I thought about his story, and I think it is true.": "../communication/audio/cau/9f8df7704c81c77d.mp3", "Pollution is a threat to wildlife.": "../skills-1/audio/cau/5c76e7f207953729.mp3", "Climate change is a big threat to our planet.": "../skills-1/audio/cau/b8fe6d86294788a6.mp3", "Many animals are threatened by hunting.": "../looking-back/audio/cau/16449b2b34e3ea0a.mp3", "The storm threatened the small town.": "../looking-back/audio/cau/edbf2277454f3343.mp3", "The sky looked dark and threatening.": "../getting-started/audio/cau/e754cc29705da6d3.mp3", "He sent her a threatening message.": "../getting-started/audio/cau/63088e01aac30517.mp3", "Wild animals face many threats.": "../looking-back/audio/cau/54aa381d8ed3c39c.mp3", "We must stop the threats to our forests.": "../looking-back/audio/cau/5626b0f008ab042b.mp3", "Don't throw rubbish in the street.": "../skills-1/audio/cau/e442d752132dc3b6.mp3", "Nam threw the ball, and Minh caught it.": "../skills-1/audio/cau/ff94476671e3947d.mp3", "There's a big tiger on the wall.": "audio/cau/be54fb559fc16be1.mp3", "I'm staying in the Tiger Room.": "audio/cau/4f7bf1272b873728.mp3", "Today is Monday, and I have maths.": "../getting-started/audio/cau/a2c1db38d6bad1f7.mp3", "It is sunny today, so we play outside.": "../getting-started/audio/cau/43f448f8abe01280.mp3", "We worked together on the project.": "../getting-started/audio/cau/69b6290ba4ffa803.mp3", "They live together, but Minh lives alone.": "../getting-started/audio/cau/48beeee1f86eeeb3.mp3", "My grandma told me a funny story.": "audio/cau/f87f67862f96ec79.mp3", "The teacher told us to be quiet.": "audio/cau/42fba1ee1bbe34c4.mp3", "We planted a tree in the schoolyard.": "../a-closer-look-1/audio/cau/7b5aaca07b018b07.mp3", "Birds are singing in the tree.": "../a-closer-look-1/audio/cau/2617b7ef451c2a57.mp3", "There are many old trees in my village.": "../a-closer-look-1/audio/cau/826dbf2b122a8fa0.mp3", "My grandfather planted this tree twenty years ago.": "../a-closer-look-1/audio/cau/dc3f88c985c7e66b.mp3", "Our class went on a trip to Ba Vi last week.": "../a-closer-look-2/audio/cau/49052bb2aa4887c3.mp3", "The school trip was fun, and Minh enjoyed the journey.": "../a-closer-look-2/audio/cau/4af60768714d1058.mp3", "Viet Nam has a tropical climate.": "../a-closer-look-2/audio/cau/cc0eebc537622836.mp3", "Mangoes are tropical fruits.": "../a-closer-look-2/audio/cau/2f137134a023d246.mp3", "Is it true that Nam can sing well?": "../getting-started/audio/cau/b793f0302657ab80.mp3", "The story is true, not false.": "../getting-started/audio/cau/fd6a61c02d4b7fe6.mp3", "We use computers to make our visual story.": "../a-closer-look-1/audio/cau/1f9e65093a2c0cf1.mp3", "This app is very useful, and I use it every day.": "../a-closer-look-1/audio/cau/7434eb2ec1577d85.mp3", "How about + V-ing? How about going to the park?": "../a-closer-look-1/audio/cau/4bd32e061c4f1188.mp3", "In the formula, V means a verb, like 'go' or 'play'.": "../a-closer-look-1/audio/cau/2a5961c55ebdeb37.mp3", "My school is very big and beautiful.": "../a-closer-look-1/audio/cau/5cd4ea7091dbf666.mp3", "Thank you very much for your help.": "../a-closer-look-1/audio/cau/162955bdaf4118ee.mp3", "Visit our website for more information.": "../a-closer-look-2/audio/cau/ac9737600d9243d7.mp3", "Phong visited his grandparents, and they enjoyed his visit.": "../a-closer-look-2/audio/cau/24f2a12ad9734414.mp3", "Water is vital for life.": "../skills-1/audio/cau/39daf087672448ee.mp3", "Exercise is vital for good health.": "../skills-1/audio/cau/80a7541a7a838916.mp3", "I walk to school every day.": "../a-closer-look-2/audio/cau/0a109a8251b16954.mp3", "Mi walked in the park and enjoyed her walk.": "../a-closer-look-2/audio/cau/f2ec11ed20a260e3.mp3", "I want to go to the summer camp.": "audio/cau/16ac9d133b953dea.mp3", "Minh wanted a new bike, and he still wants one.": "audio/cau/74bcc5e39e26178a.mp3", "Global warming is a serious problem.": "../a-closer-look-1/audio/cau/61762974c67fd9de.mp3", "Planting trees can slow global warming.": "../a-closer-look-1/audio/cau/38636dc811dac0a4.mp3", "Nam was at home yesterday.": "../a-closer-look-1/audio/cau/faca1649a4ef8a76.mp3", "I was tired, but my friends were happy.": "../a-closer-look-1/audio/cau/e3e7c2c50296c48e.mp3", "The city has a big problem with waste.": "audio/cau/6899180825d3dc6f.mp3", "Don't waste water, because wasting water is wasteful.": "audio/cau/0b423194bddcb318.mp3", "We watch TV after dinner.": "../communication/audio/cau/8b47f4f4b321b7f8.mp3", "Nam is watching a film; his new watch is on the table.": "../communication/audio/cau/850cc4ddfbc726bf.mp3", "They are watching a cartoon now.": "../communication/audio/cau/4d078d8c29b3de5f.mp3", "Phong likes watching football; he watches it every weekend.": "../communication/audio/cau/67283f87df189657.mp3", "Can I have some water, please?": "../a-closer-look-1/audio/cau/e7f9c90ffdf43ef9.mp3", "Hoa waters the plants with rainwater.": "../a-closer-look-1/audio/cau/63d57a63a01495bc.mp3", "I play football twice a week.": "audio/cau/f42675610892504d.mp3", "Every week we have a weekly test.": "audio/cau/9b6cd05f35e45234.mp3", "We went to the summer camp last June.": "../communication/audio/cau/577b7f143e454603.mp3", "Mi usually goes by bus, but yesterday she went by bike.": "../communication/audio/cau/bf4b0b541f770b47.mp3", "The blue whale is the biggest animal.": "audio/cau/d8d93dabbe152670.mp3", "We saw a whale from the boat.": "audio/cau/992338e901637bde.mp3", "Where do you live, Lan?": "../a-closer-look-1/audio/cau/0c6d7d3df1a25694.mp3", "Where is my schoolbag, Mum?": "../a-closer-look-1/audio/cau/57a3c3d221996a0d.mp3", "Why do you like this book?": "../communication/audio/cau/f853b0b3138e4625.mp3", "'Why are you late?' 'Because I missed the bus.'": "../communication/audio/cau/c4cf7bd9b30f00fd.mp3", "We must protect wildlife.": "../communication/audio/cau/79bf8410e5c5688d.mp3", "Cuc Phuong is rich in wildlife.": "../communication/audio/cau/6a25a652c022b39c.mp3", "I will help you with your homework.": "../communication/audio/cau/09b1efdcdb577f02.mp3", "Lan will visit us tomorrow, but Nam won't come.": "../communication/audio/cau/b87ff8c1b6e3e1d4.mp3", "Ha Long Bay is a natural wonder of Viet Nam.": "../a-closer-look-2/audio/cau/b6c81cae87b891ea.mp3", "I wonder what my new teacher is like.": "../a-closer-look-2/audio/cau/2d41b1bac533182b.mp3", "Learn five new words every day.": "../a-closer-look-1/audio/cau/adb2b8f5372e6050.mp3", "Match the words with the pictures, one word for each picture.": "../a-closer-look-1/audio/cau/0c015f99a499421d.mp3", "My parents work in a hospital in Ha Noi.": "../a-closer-look-1/audio/cau/4a34bda1f13dc400.mp3", "My uncle is a hard-working worker; he works every day.": "../a-closer-look-1/audio/cau/4fe31bc354d9e0c5.mp3", "She was one of the most famous scientists in the world.": "../a-closer-look-1/audio/cau/60bcc9b6651e1a00.mp3", "Pho is famous all over the world.": "../a-closer-look-1/audio/cau/5cc0d2280fff73e9.mp3", "Would you like to live here?": "../communication/audio/cau/648fc211b3b7e91a.mp3", "I would like a villa with a big garden.": "../communication/audio/cau/af8db0397bcb6281.mp3", "Please write your name here.": "../a-closer-look-1/audio/cau/a728b2e865ff5c76.mp3", "Mi likes to write, and she wrote a story yesterday.": "../a-closer-look-1/audio/cau/a907f42938059961.mp3", "My aunt is a writer.": "../a-closer-look-1/audio/cau/0b898dc7eb5824c9.mp3", "Mi wants to be a writer because she loves to write stories.": "../a-closer-look-1/audio/cau/5ce118b1d0da266b.mp3", "Lie becomes lying: change 'ie' to y and add -ing.": "../a-closer-look-1/audio/cau/ccd0d01ed2295121.mp3", "The word 'yellow' begins with the letter y.": "../a-closer-look-1/audio/cau/413244207833f8bd.mp3", "I haven't finished my homework yet.": "../communication/audio/cau/6cf31617973456ed.mp3", "'Have you eaten yet?' 'Yes, I've already eaten.'": "../communication/audio/cau/6c1068e6d07b081c.mp3"};
